  internal bool InspectionReady{get{return root!=null;}}
  internal async void SetRoot(string value){await SetRootAsync(value);}
  async Task SetRootAsync(string value){int ticket=++inspection;root=null;Buttons();try{var detected=await Task.Run(()=>{string path=Paths.ValidateRoot(value);return Tuple.Create(path,installer.Inspect(path));});if(ticket!=inspection||IsDisposed)return;root=detected.Item1;inventory=detected.Item2;location.Text=root;for(int i=0;i<4;++i){var m=catalog.Modules[i];selected[i].Checked=inventory.Plugins.Any(x=>x.Module==m.Id)||inventory.LegacyHost&&inventory.LegacyEnabled[m.Id]||inventory.Plugins.Count==0&&!inventory.LegacyHost;}
    hint.Text=inventory.LegacyHost?"Older COT found. Keep all enabled modules selected for its one-time conversion.":"Mod Manager found. Close MMC and the game before changing files.";if(fixture==null)await Task.Run(()=>Locator.Remember(detected.Item1));RefreshVersions();}
   catch(Exception e){if(ticket!=inspection||IsDisposed)return;root=null;hint.Text=Paths.Explain(e);Note(hint.Text);}Buttons();}
  void FitLayout(){
   if(layout==null||fitting)return;fitting=true;
   try{
    float scale=layoutScale>0?layoutScale:DeviceDpi/96f;if(scale<=0)scale=1;
    bool compact=ClientSize.Height/scale<580,tiny=ClientSize.Height/scale<440;
    float[] heights=tiny?new[]{0f,50f,34f,0f,0f,4f,44f,22f}:compact?new[]{36f,64f,34f,0f,0f,5f,44f,32f}:new[]{48f,82f,34f,0f,35f,8f,47f,30f};
    var headline=layout.GetControlFromPosition(0,0);if(headline!=null)headline.Visible=!tiny;
    var guidance=layout.GetControlFromPosition(0,4);if(guidance!=null)guidance.Visible=!compact;
    for(int i=0;i<heights.Length;i++)if(i!=3&&i!=6)layout.RowStyles[i].Height=heights[i]*scale;
    layout.Padding=new Padding((int)(18*scale),(int)(10*scale),(int)(18*scale),(int)(10*scale));
    if(apply.Parent!=null)layout.RowStyles[6].Height=apply.Parent.Controls.Cast<Control>().Max(c=>c.Height+c.Margin.Vertical)+apply.Parent.Padding.Vertical+apply.Parent.Margin.Vertical+8;
    layout.PerformLayout();
    if(moduleViewport!=null){int minimum=(int)((tiny?290:310)*scale);moduleCards.Dock=DockStyle.None;moduleCards.Anchor=AnchorStyles.Top|AnchorStyles.Left;moduleCards.Margin=Padding.Empty;
     moduleCards.Width=Math.Max(0,moduleViewport.Width-SystemInformation.VerticalScrollBarWidth-2);
     moduleCards.Height=Math.Max(minimum,moduleViewport.ClientSize.Height-1);moduleViewport.AutoScrollMinSize=new Size(0,minimum);
    }
   }finally{fitting=false;}
  }
  protected override void WndProc(ref Message message){base.WndProc(ref message);if(message.Msg==0x02e0)BeginInvoke(new Action(FitLayout));}
  Plugin Installed(Module m){return inventory==null?null:inventory.Plugins.FirstOrDefault(x=>x.Module==m.Id&&x.Path.Equals("Plugins/"+m.FileName,StringComparison.OrdinalIgnoreCase));}
  bool Keeping(Module m){return VersionSelection.KeepNewer(Installed(m),targets[m.Id],explicitVersions.Contains(m.Id));}
  void RefreshVersions(){for(int i=0;i<4;++i){var m=catalog.Modules[i];var current=Installed(m);versions[i].AutoEllipsis=true;versions[i].Text=current==null?"Install "+targets[m.Id].Version+(checkedVersions.Contains(m.Id)?" · latest stable":" · bundled version"):Keeping(m)?"Installed "+current.Version+" · keeping newer version":current.Sha256==targets[m.Id].DllSha256?"Installed "+current.Version+" · up to date":"Installed "+current.Version+" → "+targets[m.Id].Version;}}
  void Buttons(){bool valid=root!=null&&location.Text==root;foreach(var item in new Control[]{browse,apply,updates,backups,remove,location})item.Enabled=!busy;foreach(var choice in selected)choice.Enabled=!busy;apply.Enabled=!busy&&valid&&selected.Any(x=>x.Checked);repair.Enabled=backups.Enabled=remove.Enabled=!busy&&valid;close.Enabled=!busy||!committing;close.Text=busy?"Cancel":"Close";}
  void Note(string message){if(InvokeRequired){BeginInvoke(new Action<string>(Note),message);return;}status.Text=message;System.Threading.ThreadPool.QueueUserWorkItem(o=>{try{lock(logSync){string path=Ace.DynastyCOT.UserStorage.Current.Resolve("Setup/Logs/collection.log");Directory.CreateDirectory(Path.GetDirectoryName(path));if(File.Exists(path)&&new FileInfo(path).Length>2*1024*1024)File.WriteAllText(path,"");File.AppendAllText(path,DateTime.UtcNow.ToString("o")+" "+message+Environment.NewLine);}}catch(IOException){}catch(UnauthorizedAccessException){}});}
  async Task Run(Func<Task> work){if(busy)return;busy=true;committing=false;cancellation=new CancellationTokenSource();progress.Visible=true;Buttons();try{await work();}catch(OperationCanceledException){Note("Cancelled. Existing installed files were not changed.");}catch(Exception e){string message=Paths.Explain(e);Note(message);ShowFailure(e,message);}finally{busy=false;committing=false;cancellation.Dispose();progress.Visible=false;Buttons();}}
  Dictionary<string,string> Review(Plan plan){var unknown=installer.Review(plan);bool ask=unknown.Count>0||plan.Inventory.LegacyHost;if(ask){string text=plan.Inventory.LegacyHost?"The older COT host will be backed up. Its enabled modules will become independent plugins. Settings/history folders stay in place.\r\n\r\n":"";if(unknown.Count>0)text+="These plugin copies are not in the known-hash catalog. Back up and replace/remove these exact files?\r\n"+String.Join("\r\n",unknown.Select(x=>x.Path+"\r\nSHA-256: "+x.Sha256));if(MessageBox.Show(this,text,"Review migration",MessageBoxButtons.OKCancel,MessageBoxIcon.Information)!=DialogResult.OK)return null;}return unknown.ToDictionary(x=>x.Path,x=>x.Sha256);}
  async Task Install(){await Run(async()=>{
   string chosen=root;Paths.Closed(fixture,chosen);var wanted=new Dictionary<string,ModuleRelease>();for(int i=0;i<4;++i)if(selected[i].Checked&&!Keeping(catalog.Modules[i]))wanted.Add(catalog.Modules[i].Id,targets[catalog.Modules[i].Id]);if(wanted.Count==0){Note("Your newer installed versions were kept. No files were changed. Check updates or explicitly choose an older version to change them.");return;}
   var fresh=await Task.Run(()=>installer.Inspect(chosen));if(fresh.LegacyHost&&catalog.Modules.Any(m=>fresh.LegacyEnabled[m.Id]&&!wanted.ContainsKey(m.Id)))throw new IOException("Keep all enabled older-COT modules selected for migration, or explicitly remove unwanted ones first.");
   string cache=fixture!=null?Path.Combine(fixture.Parent,"Downloads"):Ace.DynastyCOT.UserStorage.Current.Resolve("Downloads");
   var payloads=await Task.Run(()=>{var list=new List<PreparedModule>();foreach(var entry in wanted){var m=catalog.Get(entry.Key);if(fresh.Plugins.Any(x=>x.Path.Equals("Plugins/"+m.FileName,StringComparison.OrdinalIgnoreCase)&&x.Sha256==entry.Value.DllSha256))continue;list.Add(downloads.Prepare(m,entry.Value,cache,cancellation.Token,Note));}return list;});
   cancellation.Token.ThrowIfCancellationRequested();var older=new HashSet<string>(wanted.Where(x=>fresh.Plugins.Any(p=>p.Path.Equals("Plugins/"+catalog.Get(x.Key).FileName,StringComparison.OrdinalIgnoreCase)&&p.Version!="unknown"&&ReleaseRules.Numeric(p.Version)>ReleaseRules.Numeric(x.Value.Version))).Select(x=>x.Key));if(older.Count>0&&MessageBox.Show(this,"You selected older versions of "+String.Join(", ",older)+". Downgrade those plugins? Settings/history are kept.","Confirm older versions",MessageBoxButtons.OKCancel)!=DialogResult.OK){Note("Downgrade cancelled.");return;}var plan=await Task.Run(()=>installer.Install(chosen,wanted,payloads,older));Note(plan.Summary);var reviewed=Review(plan);if(reviewed==null){Note("Migration cancelled. No installed files changed.");return;}committing=true;Buttons();await Task.Run(()=>installer.Execute(plan,reviewed,Note));Note("Done. Open MMC and launch normally. Your backup is under Backups.");await SetRootAsync(chosen);
  });}
  async Task Updates(){await CheckVersions(true);}
  async Task CheckVersions(bool show){await Run(async()=>{
   Note("Checking version information only. No plugin downloads or installation.");
   var checks=catalog.Modules.Select(module=>Task.Run(()=>{try{var list=show?downloads.Check(module,cancellation.Token):downloads.Latest(module,cancellation.Token);var latest=VersionSelection.LatestStable(module,list);if(latest!=null)downloads.Metadata(module,latest,cancellation.Token);return Tuple.Create(module,list,latest,(string)null);}catch(OperationCanceledException){throw;}catch(Exception error){return Tuple.Create(module,new List<ModuleRelease>(),(ModuleRelease)null,error.Message);}})).ToArray();
   var result=await Task.WhenAll(checks);int failed=0;
   foreach(var row in result){var module=row.Item1;releaseChoices[module.Id]=row.Item2;if(row.Item4!=null){failed++;Note(module.Title+": "+row.Item4);continue;}checkedVersions.Add(module.Id);if(row.Item3!=null){if(!explicitVersions.Contains(module.Id))targets[module.Id]=row.Item3;catalog.KnownPlugins=(catalog.KnownPlugins??new KnownFile[0]).Concat(new[]{new KnownFile{Path="Plugins/"+module.FileName,Module=module.Id,Sha256=row.Item3.DllSha256}}).ToArray();if(inventory!=null)foreach(var item in inventory.Plugins.Where(p=>p.Module==module.Id&&p.Sha256==row.Item3.DllSha256))item.Known=true;}}
   RefreshVersions();
   if(show)using(var dialog=new UpdateForm(catalog,inventory,releaseChoices,(index,release)=>{var module=catalog.Modules[index];explicitVersions.Add(module.Id);targets[module.Id]=release;selected[index].Checked=true;RefreshVersions();Note(module.Title+" "+release.Version+" selected. Click Install / Update to apply it.");})){dialog.Icon=Icon;dialog.ShowDialog(this);}
   Note(failed==0?"Latest stable versions selected. Choose Install / Update when ready.":"Could not check "+failed+" module(s). Bundled versions remain available; newer installed versions are kept. Nothing was installed.");
  });}
  bool RepairPreview(string text,string action){using(var dialog=new Form{Text="Check & Repair",ClientSize=new Size(770,480),MinimumSize=new Size(620,350),StartPosition=FormStartPosition.CenterParent,Icon=Icon,BackColor=Theme.Background,ForeColor=Theme.Text,Font=Font,AutoScaleMode=AutoScaleMode.Dpi}){var body=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(14),ColumnCount=1,RowCount=2};body.RowStyles.Add(new RowStyle(SizeType.Percent,100));body.RowStyles.Add(new RowStyle(SizeType.Absolute,46));dialog.Controls.Add(body);var box=new TextBox{Text=DisplayText.Notes(text),Dock=DockStyle.Fill,ReadOnly=true,Multiline=true,ScrollBars=ScrollBars.Vertical,BackColor=Theme.Surface,ForeColor=Theme.Text,BorderStyle=BorderStyle.FixedSingle};body.Controls.Add(box,0,0);var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft};var cancel=new RoundedButton{Text="Cancel",Width=90,Height=34,ForeColor=Theme.Text,BackColor=Theme.Surface,DialogResult=DialogResult.Cancel};var confirm=new RoundedButton{Text=action,Width=210,Height=34,Primary=true,ForeColor=Theme.Text,BackColor=Theme.Surface,DialogResult=DialogResult.OK};buttons.Controls.Add(cancel);buttons.Controls.Add(confirm);body.Controls.Add(buttons,0,1);dialog.CancelButton=cancel;dialog.Shown+=(sender,args)=>{box.Select(0,0);cancel.Select();};return dialog.ShowDialog(this)==DialogResult.OK;}}
  async Task CheckRepair(){if(root==null)return;await Run(async()=>{
   string chosen=root;var scan=await Task.Run(()=>installer.Inspect(chosen));
   string overview="This checks exact COT component identities and known release hashes, including subfolders. An old folder alone does not prove a crash cause. No folders will be deleted.\n\n"+String.Join("\n",scan.Plugins.Select(p=>p.Path+" — "+(p.Known?"recognized":"unfamiliar; review required")+" ("+p.Module+")"));
   overview+="\n\nChecked module cards choose what to repair. Unchecked modules stay installed. Newer installed versions are kept unless you explicitly select an older release.\n\nRepair may download matching files. Conflicting program files are backed up outside Plugins. Legacy settings/history are copied and verified first; originals and current AppData values are kept.\n\nClose MMC and the game before continuing.";
   if(!RepairPreview(overview,"Prepare selected repair")){Note("Check finished. No plugin files or module data were changed.");return;}Paths.Closed(fixture,chosen);
   var wanted=new Dictionary<string,ModuleRelease>();for(int i=0;i<4;++i)if(selected[i].Checked&&!Keeping(catalog.Modules[i]))wanted[catalog.Modules[i].Id]=targets[catalog.Modules[i].Id];if(wanted.Count==0){Note("No eligible modules selected. Newer installed versions were kept.");return;}
   var older=new HashSet<string>(wanted.Where(x=>scan.Plugins.Any(p=>p.Path.Equals("Plugins/"+catalog.Get(x.Key).FileName,StringComparison.OrdinalIgnoreCase)&&p.Version!="unknown"&&ReleaseRules.Numeric(p.Version)>ReleaseRules.Numeric(x.Value.Version))).Select(x=>x.Key));
   if(older.Count>0&&MessageBox.Show(this,"You explicitly selected older versions of "+String.Join(", ",older)+". Include these downgrades in the repair?","Confirm older versions",MessageBoxButtons.OKCancel)!=DialogResult.OK)return;
   string cache=fixture!=null?Path.Combine(fixture.Parent,"Downloads"):Ace.DynastyCOT.UserStorage.Current.Resolve("Downloads");
   var payloads=await Task.Run(()=>{var list=new List<PreparedModule>();foreach(var pair in wanted)if(!scan.Plugins.Any(p=>p.Path.Equals("Plugins/"+catalog.Get(pair.Key).FileName,StringComparison.OrdinalIgnoreCase)&&p.Sha256==pair.Value.DllSha256))list.Add(downloads.Prepare(catalog.Get(pair.Key),pair.Value,cache,cancellation.Token,Note));return list;});
   var plan=await Task.Run(()=>installer.Install(chosen,wanted,payloads,older,true,cancellation.Token,Note));var unknown=installer.Review(plan);
   string final="Repair preview\n\n"+plan.Summary+"\n\n"+RepairData.Summary(plan.Migration)+" Rollback keeps copied data.\n\n"+(unknown.Count==0?"All affected program files have recognized identities/hashes.":"Review unfamiliar files before approving:\n"+String.Join("\n",unknown.Select(p=>p.Path+" ("+(p.Identity??"identity unavailable")+", "+p.Version+")\nSHA-256: "+p.Sha256)))+"\n\nOnly these exact program files will change. Backups and rollback are outside Plugins.";
   if(!RepairPreview(final,unknown.Count>0?"Approve files & repair":"Apply repair")){Note("Repair cancelled. Downloaded files may be cached; installed files and module data were not changed.");return;}
   committing=true;Buttons();string repairBackup=await Task.Run(()=>installer.Execute(plan,unknown.ToDictionary(p=>p.Path,p=>p.Sha256),Note));var after=await Task.Run(()=>installer.Inspect(chosen));
   foreach(var pair in wanted)if(!after.Plugins.Any(p=>p.Path.Equals("Plugins/"+catalog.Get(pair.Key).FileName,StringComparison.OrdinalIgnoreCase)&&p.Sha256==pair.Value.DllSha256))throw new IOException("Repair finished but module verification failed: "+pair.Key+". Keep the backup and use Backups to restore.");
   await SetRootAsync(chosen);var remaining=after.Plugins.Where(p=>!p.Path.Equals("Plugins/"+p.Module+".dll",StringComparison.OrdinalIgnoreCase)).ToArray();string result="Repair complete. Selected DLLs verified; data preserved.\n\n"+String.Join("\n",wanted.Select(p=>catalog.Get(p.Key).Title+" "+p.Value.Version+": verified"))+"\n\n"+(remaining.Length==0?"No additional recognized COT program copies remain in Plugins.":"Other COT components remain. Select their modules and check again:\n"+String.Join("\n",remaining.Select(p=>p.Path)))+"\n\nBackup: "+repairBackup+"\nUse Backups to restore this repair. Copied user data and original files are kept.\n\nThis verifies files, not live game behavior.";Note("Repair complete. Selected DLLs verified; data preserved. See the repair result and Backups.");ShowText("Repair result",result);
  });}
  async Task Remove(bool all){if(root==null)return;var ids=catalog.Modules.Where((m,i)=>all||selected[i].Checked).Select(x=>x.Id).ToArray();if(ids.Length==0)return;if(MessageBox.Show(this,"Remove "+String.Join(", ",ids.Select(x=>catalog.Get(x).Title))+"? Settings and histories are kept. A backup will be made.","Remove modules",MessageBoxButtons.OKCancel)!=DialogResult.OK)return;await Run(async()=>{var plan=await Task.Run(()=>installer.Remove(root,ids));var reviewed=Review(plan);if(reviewed==null)return;committing=true;Buttons();await Task.Run(()=>installer.Execute(plan,reviewed,Note));await SetRootAsync(root);Note("Selected plugins removed. Settings and history were kept.");});}
  async Task Backups(){if(root==null)return;var available=await Task.Run(()=>installer.Backups(root));if(available.Count==0){Note("No collection backups yet. Older COT backups remain in their original folder.");return;}Backup chosen=null;using(var dialog=new Form{Text="Restore a backup",ClientSize=new Size(680,290),StartPosition=FormStartPosition.CenterParent,Icon=Icon,BackColor=Theme.Background,ForeColor=Theme.Text,Font=Font}){var list=new ListBox{Dock=DockStyle.Fill,BackColor=Theme.Surface,ForeColor=Theme.Text};list.Items.AddRange(available.Cast<object>().ToArray());list.SelectedIndex=0;dialog.Controls.Add(list);var button=new Button{Text=((Backup)list.SelectedItem).Restorable?"Restore selected backup":"View incomplete backup details",Dock=DockStyle.Bottom,Height=42};list.SelectedIndexChanged+=(sender,args)=>button.Text=list.SelectedItem!=null&&((Backup)list.SelectedItem).Restorable?"Restore selected backup":"View incomplete backup details";dialog.Controls.Add(button);button.Click+=(s,e)=>{chosen=(Backup)list.SelectedItem;dialog.Close();};dialog.ShowDialog(this);}if(chosen!=null&&!chosen.Restorable){ShowText("Incomplete backup",chosen.ToString()+"\n\nNo program changes began in this operation. This backup cannot be restored.\nSource: "+chosen.Journal.FailureSource+"\nBackup: "+chosen.Journal.FailureBackup+"\nWindows code: "+(chosen.Journal.FailureCode==0?"not reported":chosen.Journal.FailureCode.ToString())+"\n"+chosen.Journal.FailureMessage+"\n\nDetails: "+Path.Combine(chosen.Directory,"transaction.json"));return;}if(chosen==null||MessageBox.Show(this,"Restore the plugin versions in this backup? Settings/history are kept. Restore newer backups first.","Restore backup",MessageBoxButtons.OKCancel)!=DialogResult.OK)return;await Run(async()=>{committing=true;Buttons();await Task.Run(()=>installer.Restore(root,chosen.Directory));await SetRootAsync(root);Note("Backup restored. Restart MMC and the game.");});}
  void ShowFailure(Exception failure,string message){
   bool denied=false;for(var cause=failure;cause!=null;cause=cause.InnerException)if(cause is UnauthorizedAccessException)denied=true;
   if(Paths.AntivirusCode(failure)!=0)denied=false;
   if(!denied||fixture!=null){ShowText("Operation stopped",message);return;}
   using(var dialog=new Form{Text="Permission needed",ClientSize=new Size(720,350),StartPosition=FormStartPosition.CenterParent,Icon=Icon,BackColor=Theme.Background,Font=Font}){
    var text=new TextBox{Text=message+Environment.NewLine+Environment.NewLine+"You can move MMC to a folder you can write to, or reopen setup with administrator permission. Review your module choices again before installing.",Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BackColor=Theme.Surface,ForeColor=Theme.Text};dialog.Controls.Add(text);
    var retry=new Button{Text="Reopen setup as administrator",Dock=DockStyle.Bottom,Height=40};dialog.Controls.Add(retry);retry.Click+=(s,e)=>{try{string arguments=root==null?"":"--manager \""+root+"\"";Process.Start(new ProcessStartInfo(Application.ExecutablePath,arguments){UseShellExecute=true,Verb="runas"});dialog.Close();}catch(System.ComponentModel.Win32Exception error){Note(error.NativeErrorCode==1223?"Administrator request cancelled. Installed files are unchanged.":error.Message);}};dialog.ShowDialog(this);
   }
  }
  void ShowText(string title,string text){using(var dialog=new Form{Text=title,ClientSize=new Size(800,480),StartPosition=FormStartPosition.CenterParent,Icon=Icon,BackColor=Theme.Background}){var box=new TextBox{Text=DisplayText.Notes(text),Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,Font=new Font("Consolas",9),BackColor=Theme.Surface,ForeColor=Theme.Text};dialog.Controls.Add(box);dialog.ShowDialog(this);}}
  internal void SetPreviewScale(float value){layoutScale=value;FitLayout();}
  internal void AuditLayout(){FitLayout();layout.PerformLayout();FitLayout();PerformLayout();foreach(Control control in new Control[]{apply,close,remove,backups,updates,repair}){if(!control.Visible||control.Parent.RectangleToScreen(control.Parent.ClientRectangle).Contains(control.RectangleToScreen(control.ClientRectangle))==false)throw new IOException("Footer action is clipped: "+control.Text+" bounds="+control.Bounds+" parent="+control.Parent.ClientRectangle+" window="+ClientSize+" scale="+layoutScale+" row="+layout.RowStyles[6].Height+" rows="+String.Join(",",layout.GetRowHeights()));var measured=TextRenderer.MeasureText(control.Text,control.Font);if(measured.Width>control.Width||measured.Height>control.Height)throw new IOException("Footer label is clipped: "+control.Text);}if(moduleViewport.ClientSize.Height<Math.Min(150*(layoutScale>0?layoutScale:1),ClientSize.Height*.25))throw new IOException("Module area collapsed: "+moduleViewport.ClientSize+" window="+ClientSize+" scale="+layoutScale+" fitting="+fitting+" styles="+String.Join(",",layout.RowStyles.Cast<RowStyle>().Select(x=>x.Height))+" rows="+String.Join(",",layout.GetRowHeights()));foreach(var label in descriptions){if(!label.Parent.ClientRectangle.Contains(label.Bounds))throw new IOException("Description bounds leave their card: "+label.Text+" label="+label.Bounds+" parent="+label.Parent.ClientRectangle+" card="+label.Parent.Parent.ClientRectangle+" scale="+layoutScale);var size=TextRenderer.MeasureText(label.Text,label.Font,new Size(label.Width-label.Padding.Horizontal,Int32.MaxValue),TextFormatFlags.WordBreak|TextFormatFlags.TextBoxControl);if(size.Height>label.Height-label.Padding.Vertical)throw new IOException("Module description is clipped: "+label.Text+" measured="+size+" bounds="+label.Bounds+" scale="+layoutScale);}}
 }
 internal static class Locator {
  static string Preference{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"DynastyCOT","last-manager.txt");}}
  internal static void Remember(string root){try{Directory.CreateDirectory(Path.GetDirectoryName(Preference));File.WriteAllText(Preference,root);}catch(IOException){}catch(UnauthorizedAccessException){}}
  internal static string Find(){try{if(File.Exists(Preference))return Paths.ValidateRoot(File.ReadAllText(Preference));}catch(IOException){}catch(ArgumentException){}
   foreach(var process in Process.GetProcessesByName("MMCModManager"))using(process)try{return Paths.ValidateRoot(Path.GetDirectoryName(process.MainModule.FileName));}catch(System.ComponentModel.Win32Exception){}catch(InvalidOperationException){}catch(IOException){}
   var starts=new List<string>{AppDomain.CurrentDomain.BaseDirectory,Environment.CurrentDirectory,Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"Downloads"),Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory)};
   foreach(var drive in DriveInfo.GetDrives())if(drive.DriveType==DriveType.Fixed)foreach(string part in new[]{@"Apps\CFB 27\MMC",@"Games\CFB 27\MMC",@"MMC",@"Tools\MMC"})starts.Add(Path.Combine(drive.Name,part));
   var found=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var visited=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(string start in starts.Distinct(StringComparer.OrdinalIgnoreCase))for(var directory=new DirectoryInfo(start);directory!=null;directory=directory.Parent)try{if(!visited.Add(directory.FullName))continue;var valid=Paths.ValidateRoot(directory.FullName);found.Add(valid);break;}catch(IOException){}catch(UnauthorizedAccessException){}return found.Count==1?found.First():null;
  }
 }
